    StableId take_control(){auto id=common.next_id("family");need(id.ok,"original control fact ID allocated");FamilyChoice choice;choice.kind="family_succession";choice.guardian_actor_id="sender";choice.heir_actor_id="recipient";choice.tick=common.tick();family.facts.insert(id.value,choice);family.successions.push_back(id.value);need(common.append_fact({id.value,"family_succession","family"}).ok,"original typed control head appended");common.state().metadata.player_actor_id="recipient";return id.value;}
    bool valid(){auto source=authored();VisitReplyReadContext r{common,*definitions,messages,catalog,dialogues,replies_catalog,replies,deaths,&source};return validate_visit_reply_read(r).ok;}
